#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

# Avisos push (#13): lo que solo puede hacer una persona. Sin esto la app funciona igual,
# pero la confirmación no ofrece "¿Te avisamos cuando lo arreglen?" (no hay projectId de EAS).
# Correr desde cualquier lado: bash scripts/push-setup.sh

ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
cd "$ROOT"
ENV_FILE="$ROOT/.env"
EAS="npx --yes eas-cli@latest"
PSQL="$(command -v psql || echo /opt/homebrew/opt/postgresql@16/bin/psql)"
ANDROID_PACKAGE="ar.arreglemoslacalle.app"

TOTAL_STAGES=7

banner "Avisos push: EAS, FCM, APNs y build de desarrollo"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Cuenta de Expo"
say "EAS guarda el proyecto y las credenciales de push. Hace falta una cuenta de Expo (gratis)."
open_url "https://expo.dev/signup"
step "Creá la cuenta (o entrá si ya tenés una)."
pause "Cuando tengas la cuenta, Enter para hacer login acá."
$EAS login
$EAS whoami

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Proyecto de EAS (projectId)"
say "eas init crea el proyecto en expo.dev y escribe extra.eas.projectId (y owner) en mobile/app.json."
if grep -q '"projectId"' mobile/app.json; then
  note "mobile/app.json ya tiene un projectId: salteo eas init."
else
  (cd mobile && $EAS init)
fi
grep -n '"projectId"' mobile/app.json || { warn "no encontré projectId en mobile/app.json"; exit 1; }
step "Commiteá mobile/app.json: el projectId no es secreto y la app lo necesita para pedir el token."
pause

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Android: proyecto de Firebase y google-services.json"
say "Android recibe los push por Firebase Cloud Messaging (FCM)."
open_url "https://console.firebase.google.com/"
step "Crear un proyecto (ej. arreglemos-la-calle). Google Analytics no hace falta."
step "En el proyecto: ícono de Android (Agregar app) → nombre del paquete: $ANDROID_PACKAGE → Registrar app."
step "Descargá google-services.json y guardalo como $ROOT/mobile/google-services.json"
step "El resto del asistente de Firebase (SDK, Gradle) no hace falta: lo resuelve Expo."
until [[ -f mobile/google-services.json ]]; do
  pause "No veo mobile/google-services.json todavía. Guardalo ahí y Enter."
done
node -e '
  const fs = require("fs"); const p = "mobile/app.json"; const j = JSON.parse(fs.readFileSync(p, "utf8"));
  j.expo.android.googleServicesFile = "./google-services.json";
  fs.writeFileSync(p, JSON.stringify(j, null, 2) + "\n");'
printf '  %s✓ wrote%s android.googleServicesFile → mobile/app.json\n' "$GREEN" "$RESET"
note "google-services.json identifica el proyecto de Firebase (no es la clave privada). Decidí si lo commiteás;"
note "si no, EAS Build lo necesita como variable de tipo archivo (eas env:create)."
pause

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Android: clave de FCM V1 en EAS"
say "Expo necesita una clave de cuenta de servicio para mandarle los push a FCM."
open_url "https://console.firebase.google.com/project/_/settings/serviceaccounts/adminsdk"
step "Elegí el proyecto → Configuración del proyecto → Cuentas de servicio → Generar nueva clave privada."
step "Guardá el JSON FUERA del repo (ej. ~/Downloads). Es secreto: nunca lo commitees."
pause "Cuando lo tengas, Enter para abrir eas credentials."
say "En el menú de eas credentials:"
step "Android → perfil development → Google Service Account"
step "→ Manage your Google Service Account Key for Push Notifications (FCM V1)"
step "→ Set up a Google Service Account Key for Push Notifications (FCM V1) → ruta al JSON."
(cd mobile && $EAS credentials --platform android)
step "Ya está subido a EAS: borrá el JSON de tu disco."
pause

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "iOS: clave de APNs (opcional)"
say "Para iOS hace falta una cuenta paga de Apple Developer (USD 99/año)."
if confirm "¿Configuramos iOS ahora?"; then
  open_url "https://developer.apple.com/account"
  step "Entrá con la cuenta del Apple Developer Program."
  say "En el menú de eas credentials:"
  step "iOS → perfil development → Push Notifications: Manage your Apple Push Notifications Key"
  step "→ Set up → dejá que EAS genere la clave con tu login de Apple."
  (cd mobile && $EAS credentials --platform ios)
else
  SKIPPED+=("iOS: clave de APNs (cd mobile && npx eas-cli@latest credentials --platform ios)")
fi

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Build de desarrollo"
say "Los push no andan en Expo Go en Android: hace falta una build de desarrollo en un teléfono real."
note "Ojo: el mapa en Android necesita la API key de Google Maps (ver README, Pendiente humano)."
if [[ ! -f mobile/eas.json ]] && confirm "No hay mobile/eas.json. ¿Lo creo e instalo expo-dev-client?"; then
  (cd mobile && npx expo install expo-dev-client && $EAS build:configure --platform all)
  note "Revisá que mobile/eas.json tenga el perfil development (developmentClient: true) y commitealo."
fi
if confirm "¿Lanzo la build de desarrollo de Android en EAS (tarda unos 15 min)?"; then
  (cd mobile && $EAS build --profile development --platform android)
  step "Cuando termine, abrí el link de la build en el teléfono e instalá el APK."
else
  note "Alternativa local, con el teléfono por USB: cd mobile && npx expo run:android --device"
fi
step "Con la build instalada: cd mobile && npx expo start --dev-client, y abrí la app en el teléfono."
pause

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Probar los avisos"
step "En la app: sacá una foto, mandá el reporte y en la confirmación tocá \"Sí, avisame\"."
step "Recién ahí el teléfono pide el permiso de notificaciones: aceptalo."
step "La tarjeta tiene que pasar a \"Listo, te vamos a avisar\"."
pause "Hecho eso, Enter para ver el token guardado en la base."
set -a
# shellcheck disable=SC1090
. "$ENV_FILE"
set +a
"$PSQL" "$SUPABASE_DB_URL" -c "select device_id, left(token, 30) as token, updated_at from public.push_devices order by updated_at desc limit 3"
ask REPORT_ID "Número del reporte que creaste:"
PROJECT_REF="${SUPABASE_URL#https://}"
PROJECT_REF="${PROJECT_REF%%.*}"
open_url "https://supabase.com/dashboard/project/$PROJECT_REF/editor"
step "Table Editor → reports → fila id $REPORT_ID → status: resolved → Save."
step "Con la app en segundo plano o cerrada tiene que llegar \"¡Lo arreglaron!\"."
step "Tocá el aviso: tiene que abrir el detalle del reporte $REPORT_ID."
pause "Enter para ver la respuesta de Expo al envío."
"$PSQL" "$SUPABASE_DB_URL" -c "select id, status_code, left(content, 200) as content, error_msg from net._http_response order by id desc limit 3"
note "status \"ok\" = Expo lo aceptó. DeviceNotRegistered = token viejo o de prueba."
note "InvalidCredentials = falta la clave de FCM V1 o de APNs (stages 4 y 5)."
step "Volvé el reporte a open desde el panel: tiene que llegar \"Sigue roto\"."
pause
# ──────────────────────────────────────────────────────────────────────────

finish
